    if (false) {
        check(!c.isAscii())
    }
    return (c.code.toUInt()) >= 0xc0u && bitsetSearch(c.code.toUInt(), BITSET_CHUNKS_MAP, BITSET_INDEX_CHUNKS, BITSET_CANONICAL, BITSET_MAPPING)
